--
-- Name: escape_html(text); Type: FUNCTION; Schema: zulip; Owner: -
--

CREATE FUNCTION zulip.escape_html(text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
              SELECT replace(replace(replace(replace(replace($1, '&', '&amp;'), '<', '&lt;'),
                                             '>', '&gt;'), '"', '&quot;'), '''', '&#39;');
            $_$;


